-- Cambio incremental e idempotente para la base existente creada con EnsureCreated.
-- Aplicar con una conexión directa, primero en una rama de prueba de Neon.
CREATE TABLE IF NOT EXISTS "Rankings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PlayerName" character varying(60) NOT NULL,
    "Score" integer NOT NULL,
    "Time" real NOT NULL,
    "CharacterId" integer NOT NULL,
    "Date" character varying(64) NOT NULL,
    "Uploaded" boolean NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_Rankings_Score_Time_Id"
    ON "Rankings" ("Score" DESC, "Time" ASC, "Id" ASC);
